{
  "type": "function",
  "name": "cascade__move_home",
  "description": "Return the arm to its configured INITIAL (ready) pose. Reobserve after moving an eye-in-hand camera. On a rig with a separate rest pose this means raised, motors on, gripper closed and the arm stops powered, so recovery is just issuing the correct command. Not the raised initial/ready pose -- that is move_home. If the arm does not reach the rest pose the motors stay ON (a raised arm without torque would fall) and the result says why. Say the robot can be switched off ONLY when the result has safe_to_power_off=true. keep_torque=true folds it but keeps the motors on. The next motion command switches the motors on again by itself. An arm with no folded rest pose goes to its initial pose instead (safe_to_power_off=false).",
  "parameters": {
    "type": "object",
    "properties": {
      "keep_torque": {
        "type": "boolean",
        "description": "Keep the motors on at the rest pose (default false: they are switched off)."
      }
    }
  },
  "return_state": {
    "has_arm_moved": false,
    "arm_is_ready": true,
    "gripper_is_closed": true,
    "gripper_is_holding": false
  }
}
